193:                 int nextRowIdx = appIdx + columnsPerRow;
194:                 if (nextRowIdx >= appViews.size()) {
195:                     // Navigate from Apps Bottom Row down to Footer
196:                     if (!footerViews.isEmpty()) {
197:                         int target = Math.min(col, footerViews.size() - 1);
198:                         requestFocusOn(footerViews.get(target));
