209:             if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
210:                 if (!appViews.isEmpty()) {
211:                     int target = Math.min(headerIdx, Math.min(columnsPerRow - 1, appViews.size() - 1));
