224:         int footerIdx = findKeyIndex(footerViews, currentKey);
225:         if (footerIdx >= 0) {
226:             if (keyCode == KeyEvent.KEYCODE_DPAD_UP) {
227:                 if (!appViews.isEmpty()) {
228:                     int totalApps = appViews.size();
229:                     int fullRows = totalApps / columnsPerRow;
230:                     int remainder = totalApps % columnsPerRow;
231:                     int target;
232:                     if (remainder == 0 || footerIdx < remainder) {
233:                         target = (fullRows - (remainder == 0 ? 1 : 0)) * columnsPerRow + Math.min(footerIdx, (remainder == 0 ? columnsPerRow : remainder) - 1);
