296:         else if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) step = 1;
297:         else if (keyCode == KeyEvent.KEYCODE_DPAD_UP) step = -columnsPerRow;
298:         else if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) step = columnsPerRow;
299: 
300:         if (step != 0) {
301:             if (isDown) {
302:                 int from = findKeyIndex(appViews, key);
303:                 int to = from + step;
304:                 if (from >= 0 && from < appViews.size() && to >= 0 && to < appViews.size()) {
305:                     appViews.add(to, appViews.remove(from));
306:                     callback.onMoveStep(key, from, to);
307:                 }
308:             }
309:             return true;
310:         }
311: 
