298: 
299:             // Sideloaded app banner generator: synthesize 16:9 banner canvas from app icon
300:             if (banner == null && icon != null) {
301:                 try {
302:                     banner = BannerGenerator.getInstance().getOrCreateBannerDrawable(
303:                             getResources(), pkg, label, icon, tileW, tileH);
304:                 } catch (Exception ignored) {}
305:             }
306: 
307:             View card = addTile(root, pkg, label, banner, null, icon, gridX(i), gridY(i), tileW, tileH, true);
308:             appCards.add(card);
309:         }
310: 
311:         // 2. Footer Row: Play Store, HDMI inputs, Settings, Add App
312:         int col = 0;
313:         boolean showStore = !rowApps.contains(PLAY_STORE) && getLaunchIntent(pm, PLAY_STORE) != null;
314:         List<TvInputHelper.HdmiInput> inputs = TvInputHelper.queryHdmiInputs(this, 4);
315:         int maxInputs = PER_ROW - 2 - (showStore ? 1 : 0);
316:         if (inputs.size() > maxInputs) {
317:             inputs = inputs.subList(0, maxInputs);
318:         }
319: 
320:         if (showStore) {
321:             addTile(root, PLAY_STORE, "Play Store", null, LineIcon.PLAY, null,
322:                     m + col++ * (tileW + g), bottomTop, tileW, tileH, false);
323:         }
324: 
325:         for (TvInputHelper.HdmiInput in : inputs) {
326:             addTile(root, in.id, in.label, null, LineIcon.HDMI, null,
327:                     m + col++ * (tileW + g), bottomTop, tileW, tileH, false);
328:         }
329: 
330:         addTile(root, SETTINGS_ACTION, Strings.t("Settings"), null, LineIcon.SETTINGS, null,
331:                 m + col++ * (tileW + g), bottomTop, tileW, tileH, false);
332: 
333:         addTile(root, ADD, Strings.t("Add app"), null, LineIcon.PLUS, null,
334:                 m + col * (tileW + g), bottomTop, tileW, tileH, false);
335: 
336:         // 3. Header Zone: Quick Settings shortcuts & Network Tile
337:         buildHeaderIcons(m);
338: 
339:         root.setDescendantFocusability(ViewGroup.FOCUS_AFTER_DESCENDANTS);
340:         focusController.restoreFocus(lastFocus, lastIndex);
341:     }
