343:     private void buildHeaderIcons(int margin) {
344:         List<String> quickShortcuts = (config != null && config.quickSettings != null)
345:                 ? config.quickSettings : new ArrayList<>();
346: 
347:         int ib = px(ICON_BUTTON), ig = px(ICON_GAP);
348:         int totalHeaderIcons = quickShortcuts.size() + 1; // plus network icon
349:         int qx = getResources().getDisplayMetrics().widthPixels - margin + (ib - px(ICON_SIZE)) / 2
350:                 - totalHeaderIcons * ib - (totalHeaderIcons - 1) * ig;
351: 
352:         for (String name : quickShortcuts) {
353:             int[] iconOps = getIconForShortcut(name);
354:             if (iconOps != null) {
355:                 addHeaderIcon(QUICK_PREFIX + name, Strings.t(capitalize(name)), new LineIcon(iconOps, px(ICON_SIZE)), qx);
356:                 qx += ib + ig;
357:             }
358:         }
359: 
360:         netIcon = addHeaderIcon(NETWORK, Strings.t("Network"), null, qx);
361:         netState = -1;
362:         refreshNetwork();
363:     }
