545:     private void showEditMenu(final String key) {
546:         final int index = rowApps.indexOf(key);
547:         if (index < 0) return;
548:         boolean userApp = isUserInstalled(key);
549:         String[] items = userApp ? EDIT_ITEMS_USER : EDIT_ITEMS_SYSTEM;
550: 
551:         View card = findTile(key);
552:         if (card == null) return;
553: 
554:         dropdown(card, items, which -> {
555:             if (which == 0) {
556:                 // Move Mode
557:                 initialAppsBeforeMove = new ArrayList<>(rowApps);
558:                 moveHint.setVisibility(View.VISIBLE);
559:                 focusController.startMove(key, card);
560:             } else if (which == 1) {
561:                 // Replace
562:                 showAddMenu(index);
563:             } else if (which == 2) {
564:                 // Remove from home
565:                 rowApps.remove(index);
566:                 persistApps();
567:                 buildTiles();
568:             } else if (which == 3) {
569:                 // Uninstall or App info
570:                 Uri packageUri = Uri.parse("package:" + key);
571:                 try {
572:                     Intent intent = userApp ? new Intent(Intent.ACTION_DELETE, packageUri)
573:                             : new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, packageUri);
574:                     startActivity(intent);
575:                 } catch (Exception ignored) {}
576:             }
577:         });
578:     }
