580:     private void showAddMenu(final int replaceIndex) {
581:         PackageManager pm = getPackageManager();
582:         TreeMap<String, String> byLabel = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
583: 
584:         for (String category : new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER, Intent.CATEGORY_LAUNCHER}) {
585:             Intent q = new Intent(Intent.ACTION_MAIN).addCategory(category);
586:             List<ResolveInfo> list = pm.queryIntentActivities(q, 0);
587:             for (ResolveInfo ri : list) {
588:                 if (ri.activityInfo == null) continue;
589:                 String pkg = ri.activityInfo.packageName;
590:                 if (rowApps.contains(pkg) || byLabel.containsValue(pkg) || pkg.equals(getPackageName())) {
591:                     continue;
592:                 }
593:                 String label = labelOf(pkg);
594:                 if (!byLabel.containsKey(label)) {
595:                     byLabel.put(label, pkg);
596:                 }
597:             }
598:         }
599: 
600:         if (byLabel.isEmpty()) {
601:             panel(Strings.t("Every app is already here"), Collections.singletonList("OK"), which -> {});
602:             return;
603:         }
604: 
605:         final List<String> pkgs = new ArrayList<>(byLabel.values());
606:         String title = replaceIndex < 0 ? Strings.t("Add an app")
607:                 : String.format(Strings.t("Replace %s"), labelOf(rowApps.get(replaceIndex)));
608: 
609:         panel(title, new ArrayList<>(byLabel.keySet()), pos -> fit(pm.getApplicationIcon(pkgs.get(pos)), px(48), px(48)),
610:                 px(48), -1, null, which -> {
611:                     if (replaceIndex < 0) {
612:                         rowApps.add(pkgs.get(which));
613:                     } else {
614:                         rowApps.set(replaceIndex, pkgs.get(which));
615:                     }
616:                     persistApps();
617:                     buildTiles();
618:                 });
619:     }
