669:     private void dropdown(View anchor, String[] items, final Pick pick) {
670:         final Dialog d = new Dialog(this, android.R.style.Theme_Material_Dialog_NoActionBar);
671:         LinearLayout box = new LinearLayout(this);
672:         box.setOrientation(LinearLayout.VERTICAL);
673:         int pad = px(10), rowH = px(64);
674:         box.setPadding(pad, pad, pad, pad);
675: 
676:         GradientDrawable bg = new GradientDrawable();
677:         bg.setCornerRadius(px(RADIUS));
678:         bg.setColor(0xFF231D1F);
679:         bg.setStroke(Math.max(1, px(2)), 0x17FFFFFF);
680:         box.setBackground(bg);
681: 
682:         float widest = 0;
683:         for (int i = 0; i < items.length; i++) {
684:             final int which = i;
685:             final TextView t = createTextView(px(26), 0xD9FFFFFF, regular);
686:             t.setText(Strings.t(items[i]));
687:             t.setSingleLine(true);
688:             t.setGravity(Gravity.CENTER_VERTICAL);
689:             t.setPadding(px(22), 0, px(22), 0);
690:             widest = Math.max(widest, t.getPaint().measureText(t.getText().toString()) + 2 * px(22) + 2 * pad);
691: 
692:             final GradientDrawable focus = new GradientDrawable();
693:             focus.setCornerRadius(px(RADIUS - pad));
694:             focus.setColor(Color.TRANSPARENT);
695:             t.setBackground(focus);
696:             t.setFocusable(true);
697:             t.setOnFocusChangeListener((v, has) -> {
698:                 focus.setColor(has ? 0x38FFFFFF : Color.TRANSPARENT);
699:                 t.setTextColor(has ? Color.WHITE : 0xD9FFFFFF);
700:             });
701:             t.setOnClickListener(v -> {
702:                 d.dismiss();
703:                 pick.at(which);
704:             });
705:             box.addView(t, new LinearLayout.LayoutParams(-1, rowH));
706:         }
707:         d.setContentView(box);
708: 
709:         int h = items.length * rowH + 2 * pad;
710:         int w;
711:         int x = 0;
712:         int y = 0;
713:         int gravity;
714: 
715:         if (anchor != null) {
716:             int[] at = new int[2];
717:             anchor.getLocationOnScreen(at);
718:             int tileBottom = at[1] + Math.round(anchor.getHeight() * anchor.getScaleY());
719:             w = Math.max(Math.max(Math.round(anchor.getWidth() * anchor.getScaleX()), px(320)), (int) Math.ceil(widest));
720:             y = tileBottom + px(64);
721:             if (y + h > getResources().getDisplayMetrics().heightPixels - px(24)) {
722:                 y = at[1] - h - px(16);
723:             }
724:             x = at[0];
725:             gravity = Gravity.TOP | Gravity.START;
726:         } else {
727:             // Anchor view is null: fallback to center-screen placement
728:             w = Math.max(px(320), (int) Math.ceil(widest));
729:             x = 0;
730:             y = 0;
731:             gravity = Gravity.CENTER;
732:         }
733: 
734:         Window win = d.getWindow();
735:         if (win != null) {
736:             win.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
737:             win.clearFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);
738:             win.setGravity(gravity);
739:             android.view.WindowManager.LayoutParams lp = win.getAttributes();
740:             lp.x = x;
741:             lp.y = y;
742:             lp.width = w;
743:             lp.height = h;
744:             win.setAttributes(lp);
745:         }
746:         d.show();
747:     }
