118:      * 1. Google TV Input Player (if resolved default)
119:      * 2. Stock AOSP / OEM Live TV (com.android.tv, com.droidlogic.android.tv, com.mediatek.tv)
120:      * 3. Generic Action View on Passthrough URI
121:      */
122:     public static List<Intent> buildLaunchIntents(Context context, String inputId) {
123:         List<Intent> intents = new ArrayList<>();
124:         if (context == null || inputId == null || inputId.trim().isEmpty()) {
125:             return intents;
126:         }
127:         PackageManager pm = context.getPackageManager();
128:         Uri uri = TvContract.buildChannelUriForPassthroughInput(inputId);
129:         Intent baseView = new Intent(Intent.ACTION_VIEW, uri);
130: 
131:         // 1. Google TV Input Player
132:         try {
133:             ResolveInfo def = pm.resolveActivity(baseView, PackageManager.MATCH_DEFAULT_ONLY);
134:             if (def != null && def.activityInfo != null && INPUT_PLAYER.equals(def.activityInfo.packageName)) {
135:                 intents.add(new Intent(baseView).setClassName(INPUT_PLAYER, def.activityInfo.name));
136:             }
137:         } catch (Exception ignored) {}
138: 
139:         // 2. Known OEM Live TV Handlers (AOSP Live TV, Droidlogic, MediaTek)
140:         for (String[] target : LIVE_TV_HANDLERS) {
141:             Intent t = new Intent(baseView).setClassName(target[0], target[1]);
142:             try {
143:                 if (t.resolveActivity(pm) != null) {
144:                     intents.add(t);
145:                 }
146:             } catch (Exception ignored) {}
147:         }
148: 
149:         // 3. Generic Action View on Passthrough URI
150:         intents.add(baseView);
151:         return intents;
152:     }
