204:     @Test
205:     public void testSymmetricalGridScaling1080pAnd4K() {
206:         int margin = 96, gap = 36, perRow = 6;
207: 
208:         // 1. 1080p Display (1920x1080)
209:         int width1080 = 1920;
210:         float scale1080 = width1080 / 1920.0f;
211:         assertEquals(1.0f, scale1080, 0.0001f);
212:         int m1080 = Math.round(margin * scale1080);
213:         int g1080 = Math.round(gap * scale1080);
214:         int tileW1080 = (width1080 - 2 * m1080 - g1080 * (perRow - 1)) / perRow;
215:         int tileH1080 = Math.round(tileW1080 * 9.0f / 16.0f);
216: 
217:         assertEquals(96, m1080);
218:         assertEquals(36, g1080);
219:         assertEquals(258, tileW1080);
220:         assertEquals(145, tileH1080);
221: 
222:         // Verify total row width and strict symmetry
223:         int rowSpan1080 = perRow * tileW1080 + (perRow - 1) * g1080;
224:         int leftMargin1080 = m1080;
225:         int rightMargin1080 = width1080 - (leftMargin1080 + rowSpan1080);
226:         assertEquals(leftMargin1080, rightMargin1080);
227:         assertEquals(96, rightMargin1080);
228: 
229:         // 2. 4K UHD Display (3840x2160)
230:         int width4k = 3840;
231:         float scale4k = width4k / 1920.0f;
232:         assertEquals(2.0f, scale4k, 0.0001f);
233:         int m4k = Math.round(margin * scale4k);
234:         int g4k = Math.round(gap * scale4k);
235:         int tileW4k = (width4k - 2 * m4k - g4k * (perRow - 1)) / perRow;
236:         int tileH4k = Math.round(tileW4k * 9.0f / 16.0f);
237: 
238:         assertEquals(192, m4k);
239:         assertEquals(72, g4k);
240:         assertEquals(516, tileW4k);
241:         assertEquals(290, tileH4k);
242: 
243:         // Verify total row width and strict symmetry
244:         int rowSpan4k = perRow * tileW4k + (perRow - 1) * g4k;
245:         int leftMargin4k = m4k;
246:         int rightMargin4k = width4k - (leftMargin4k + rowSpan4k);
247:         assertEquals(leftMargin4k, rightMargin4k);
248:         assertEquals(192, rightMargin4k);
249: 
250:         // Exact 2x scale proportionality
251:         assertEquals(m1080 * 2, m4k);
252:         assertEquals(g1080 * 2, g4k);
253:         assertEquals(tileW1080 * 2, tileW4k);
254:         assertEquals(tileH1080 * 2, tileH4k);
255:     }
